import { useDisplay } from "vuetify/lib/framework.mjs";
import { edit_timesheet_manegement_settings } from "@/graphql/mutations.js";
import { get_Org_details } from "@/mixins/GetOrgDetails.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    SnackBar
  },
  mixins: [get_Org_details],
  data() {
    return {
      height: 0,
      prezenceEnable: null,
      approvalEnable: null,
      dailyfillEnable: null,
      loading: false,
      SnackBarComponent: {},
      CommonVuetifyObj: {}
    };
  },
  created() {
    this.prezenceEnable = this.$store.getters.GetOrgDetails.organization.is_attendance_management == undefined || this.$store.getters.GetOrgDetails.organization.is_attendance_management == false ? "false" : "true";
    this.approvalEnable = this.$store.getters.GetOrgDetails.organization.timesheet_approval_required == undefined || this.$store.getters.GetOrgDetails.organization.timesheet_approval_required == false ? "false" : "true";
    this.dailyfillEnable = this.$store.getters.GetOrgDetails.organization.is_daily_timesheet_required == undefined || this.$store.getters.GetOrgDetails.organization.is_daily_timesheet_required == true ? "true" : "false";
  },
  mounted() {
    this.CommonVuetifyObj = useDisplay();
  },
  methods: {
    async validate_user() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(edit_timesheet_manegement_settings, {
          input: {
            organization_id: data.organization.organization_id,
            is_attendance_management: this.prezenceEnable == "true" ? true : false,
            timesheet_approval_required: this.approvalEnable == "true" ? true : false,
            is_daily_timesheet_required: this.dailyfillEnable == "true" ? true : false
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.edit_timesheet_manegement_settings);
        if (response.Status == "SUCCESS") {
          await this.get_Org_details();
          this.prezenceEnable = this.$store.getters.GetOrgDetails.organization.is_attendance_management == undefined || this.$store.getters.GetOrgDetails.organization.is_attendance_management == false ? "false" : "true";
          this.approvalEnable = this.$store.getters.GetOrgDetails.organization.timesheet_approval_required == undefined || this.$store.getters.GetOrgDetails.organization.timesheet_approval_required == false ? "false" : "true";
          this.dailyfillEnable = this.$store.getters.GetOrgDetails.organization.is_daily_timesheet_required == undefined || this.$store.getters.GetOrgDetails.organization.is_daily_timesheet_required == false ? "false" : "true";
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
          await this.get_Org_details();
          this.prezenceEnable = this.$store.getters.GetOrgDetails.organization.is_attendance_management == undefined || this.$store.getters.GetOrgDetails.organization.is_attendance_management == false ? "false" : "true";
        }
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
